const boldItal = await doc.embedFont(StandardFonts.TimesRomanBoldItalic);

/** Anotasi tautan agar DOI/URL pada daftar pustaka dapat diklik di penampil PDF. */
const linkRect = (pg: PDFPage, url: string, x: number, y: number, w: number, h: number) => {
	const ctx = doc.context;
	const annot = ctx.obj({
		Type: 'Annot', Subtype: 'Link',
		Rect: [x, y, x + w, y + h],
		Border: [0, 0, 0],
		A: { Type: 'Action', S: 'URI', URI: url },
	});
	const key = PDFName.of('Annots');
	const existing = pg.node.lookupMaybe(key, PDFArray);
	const arr = existing ?? (ctx.obj([]) as PDFArray);
	if (!existing) { pg.node.set(key, arr); }
	arr.push(annot as never);
};

